audit_log_title: "감사 로그",
audit_log_description: "수행한 파괴적이고 되돌릴 수 없는 작업의 영구 로컬 기록입니다. 지우기 버튼 없음 — 의도적입니다. 최근 100개 항목이 표시됩니다. 오래된 항목은 링 버퍼에서 빠져나갑니다.",
