a11y_color_blind_hint: "선택한 색각 유형에서도 구분되도록 상태 색상(성공/경고/오류)을 조정합니다.",
a11y_density_hint: "앱 전체의 간격과 여백을 조절합니다. 넓게는 터치 입력을 위한 여유를 늘리고, 좁게는 화면에 더 많은 내용을 표시합니다.",
a11y_high_contrast_hint: "텍스트, 테두리, 포커스 링의 의미적 색상 대비를 강화합니다.",
a11y_motion_hint: "자동은 OS 설정을 따릅니다. 줄임은 전환을 0.4배 속도로 재생하고, 없음은 완전히 끕니다.",
a11y_sr_hints_hint: "추가 맥락을 읽어 주는 상세한 aria 레이블을 넣습니다(예: 단순히 “버튼”이 아니라 “연결 새로 고침”).",
activity_preparing_hint: "준비 중… 아직 전송된 데이터가 없습니다. 압축 파일(.zip/.rar/.7z)은 먼저 컴퓨터에서 풀립니다. 큰 파일은 업로드 속도가 표시되기까지 시간이 걸릴 수 있습니다.",
backup_delete_confirm_msg: "{tag} @ {ts}을(를) 삭제할까요? 되돌릴 수 없습니다.",
