backup_warning: "스냅샷은 PS5의 /data/ps5upload/backups/ 에 저장됩니다. 복원하면 원래 경로의 기존 파일을 덮어씁니다.",
bringup_chain_with: "{name} → 헬퍼 → 자동 로더",
bringup_desc: "한 번에: 초기 구동 페이로드를 불러오고, 헬퍼를 보낸 뒤 PS5가 준비될 때까지 기다립니다.",
bringup_failed: "{phase} 단계에서 구동 실패: {error}",
bringup_phase_prehelper: "초기 구동 페이로드를 불러오는 중({name})…",
cheats_description: "실행 중인 게임에 메모리 패치를 적용합니다. JSON, SHN, 패치 파일을 지원합니다.",
cheats_search_hint: "게임 이름이나 타이틀 ID(예: CUSA00001)를 입력하고 검색을 누르세요",
connection_step2_browser_unsupported: "브라우저는 보낼 로컬 헬퍼 파일을 읽을 수 없습니다. 데스크톱 앱이나 USB 자동 로더로 헬퍼를 먼저 불러오면 이 페이지가 자동으로 감지합니다.",
dashboard_running_apps: "실행 중인 앱({n})",
engine_url_hint: "앱이 ps5upload-engine에 접속하는 위치입니다. 기본 로컬 sidecar를 그대로 두거나 원격/자체 호스팅 엔진을 지정하세요. 로컬과 원격을 전환한 뒤에는 앱을 다시 시작하세요.",
err_fs_read_path_not_allowed: "이 파일은 보통 차단되는 읽기 전용 시스템 파티션에 있습니다. 설정 → “시스템 파일 다운로드 허용”을 켜면 /system, /system_data 등 보호된 경로에서 읽을 수 있습니다. 다운로드에만 적용되며, 그곳에서 삭제·이동·쓰기는 절대 허용되지 않습니다.",
err_rar_open_failed: "이 RAR 파일을 읽을 수 없습니다. 분할 압축이라면 첫 번째 파일(…part1.rar / …part01.rar / ….rar)을 선택하고 모든 분할 파일이 같은 폴더에 있는지 확인하세요. 비밀번호가 걸려 있다면 비밀번호를 입력하세요.",
err_rar_password_required: "이 RAR 파일은 비밀번호로 보호되어 있습니다. 내용을 읽고 업로드하려면 아래에 비밀번호를 입력하세요.",
err_rar_unsafe_entry: "이 RAR에는 대상 폴더 밖을 가리키는 파일 경로가 있어 안전을 위해 거부되었습니다. 파일이 손상되었을 수 있습니다.",
err_rar_unsupported: "이 빌드에서는 RAR을 지원하지 않습니다(안드로이드는 .zip과 .7z만 업로드). 먼저 컴퓨터에서 .rar을 풀거나 데스크톱 앱을 사용하세요.",
fanCurve_hint: "온도-듀티 포인트를 정의합니다. PS5가 그 사이를 보간합니다.",
fanCurve_persisted: "이 PS5에 팬 커브가 저장되어 있습니다. 첫 포인트의 온도가 현재 팬 임계값이며, 페이로드를 불러올 때마다 자동으로 복원됩니다. 데스크톱 앱은 필요 없습니다.",
fs_download_zip_dialog_title: "“{name}”을(를) .zip으로 저장",
fs_install_confirm_body_usb: "패키지를 내부 저장소에 임시로 올린 뒤(콘솔은 USB에서 바로 설치할 수 없습니다) 설치하고, 임시 사본을 지웁니다. 드라이브의 원본은 그대로 둡니다.",
fs_install_confirm_title: "“{name}”을(를) 설치할까요?",
fs_install_done: "{name} 설치됨",
fs_install_may_not_launch: "설치는 등록되었지만 타이틀이 실행되지 않을 수 있습니다. 설치된 앱을 확인하세요.",
fs_op_on_other_console: "{name}에서 파일 작업이 진행 중입니다. 해당 콘솔 탭으로 전환해 진행 상황을 확인하세요.",
fs_path_gone_body: "{path}은(는) 더 이상 PS5에 없습니다.",
fs_rename_target_exists: "여기에 “{name}”이라는 항목이 이미 있습니다. 이름을 바꾸면 덮어쓰게 됩니다. 다른 이름을 쓰거나 먼저 삭제하세요.",
fw_spoof_kernel_unknown_warn: "커널 버전을 읽지 못했습니다. 위조 감지가 정확하지 않을 수 있습니다.",
game_hub_launch_unconfirmed_body: "PS5가 실행 요청을 받아들였지만 타이틀이 아직 나타나지 않았습니다. 콘솔을 확인하세요. 아직 시작 중일 수 있습니다.",
game_hub_media_not_per_game: "PS5는 스크린샷이나 클립에 어떤 게임에서 나온 것인지 표시하지 않습니다. 타이틀이 아니라 날짜별로 보관됩니다. 콘솔에서 전체를 살펴보세요:",
