game_hub_no_updates: "이 타이틀에 준비된 업데이트 패키지가 없습니다. 패키지 설치에서 업로드하세요.",
installed_all_played: "ps5upload가 열려 있는 동안 설치된 모든 타이틀이 플레이 중으로 확인되었습니다. 미사용으로 표시된 항목이 없습니다.",
