installed_playtime_line: "{time} · 마지막 확인 {seen}",
installed_playtime_tooltip: "플레이 시간과 마지막 확인은 ps5upload가 열려 관찰 중일 때만 기록됩니다. 콘솔 자체 기록이 아닙니다.",
installed_stop_confirm_body: "PS5에서 실행 중인 게임을 닫습니다. 저장하지 않은 진행 상황은 사라집니다. 콘솔에서 종료하는 것과 같습니다.",
