about_disclaimer_title: "면책 조항",
about_disclaimer_purpose: "ps5upload는 연구, 교육, 상호 운용성 및 홈브루 개발 목적으로만 제공됩니다. 소니 인터랙티브 엔터테인먼트와 제휴하거나 승인을 받았거나 연결되어 있지 않습니다. “PlayStation”과 “PS5”는 소니 인터랙티브 엔터테인먼트의 상표이며, 여기서는 식별 목적으로만 사용되었습니다.",
about_disclaimer_piracy: "본인이 소유한 하드웨어와 적법하게 보유한 콘텐츠에만 사용하십시오. 사용 권한이 없는 소프트웨어를 복사, 배포하거나 실행하는 데 사용해서는 안 됩니다.",
about_disclaimer_risk: "이 소프트웨어는 어떠한 보증도 없이 “있는 그대로” 제공됩니다. 개조된 본체를 사용하면 본체가 영구적으로 손상되거나, 저장 데이터와 라이선스가 복구 불가능하게 사라지거나, 계정 또는 본체가 정지될 수 있습니다. 사용에 따른 위험은 전적으로 본인이 부담하며 그 결과에 대한 모든 책임을 집니다. 시작하기 전에 잃어서는 안 될 모든 것을 백업하십시오.",
about_disclaimer_read_full: "전체 약관 읽기",
backup_explain: "나중에 되돌릴 수 있도록 본체의 파일을 이 컴퓨터로 복사합니다. 아래에서 일반적인 항목을 고르거나 직접 경로를 입력하십시오.",
