err_rar_missing_volume: "이 분할 RAR 파일이 불완전합니다. 폴더에 {file}이(가) 없습니다. 해당 부분을 내려받거나 복사해 넣은 뒤 다시 시도하십시오.",
fakelib_no_titles_desc: "폴더로 설치된 게임만 대체 라이브러리를 사용할 수 있습니다. 디스크 이미지에서 마운트된 타이틀은 읽기 전용입니다.",
