game_activity_reset_explain: "이 작업은 ps5upload가 이 본체에서 기록한 플레이 시간을 영구적으로 삭제합니다. 되돌릴 수 없으며 지난 세션도 복구할 수 없습니다. 본체 자체의 기록에는 영향을 주지 않으며, 이 화면에 표시된 내용만 지웁니다.",
