"pkglib.installAll.what": "“모두 설치”란?",
"pkglib.installAll.whatBody": "“모두 설치”는 준비된 모든 패키지를 순서대로 처리합니다: 기본 게임 → 업데이트 → DLC. 같은 버전의 업데이트가 두 개이거나 충돌하는 DLC가 두 개인 경우, 각 행의 체크박스로 이 본체가 설치할 항목을 고르십시오. 그룹당 하나만 선택할 수 있습니다. 체크를 해제하면 해당 그룹은 제외됩니다. 개별 행의 설치 버튼은 언제나 그 패키지만 설치합니다.",
