"power_wake_code_save": "저장",
"power_wake_code_hint": "본체의 리모트 플레이 등록 키를 숫자로 나타낸 것입니다. Chiaki 사용자: 등록된 본체의 키입니다.",
"power_wake_code_invalid": "켜기 코드처럼 보이지 않습니다 — 원시 키가 아니라 숫자여야 합니다.",
"power_wake_ready": "대기 모드에서 켜기가 설정되었습니다",
"power_wake_ready_toast": "이제 이 본체를 켤 수 있습니다",
"power_wake_ready_body": "설정되었습니다. 위의 본체 설정이 켜져 있는 한 대기 모드에서 켜기가 작동합니다.",
