"connection_prior_killed_detail": "콘솔의 다른 페이로드가 종료했거나, 시스템 메모리가 부족했거나, 충돌했을 수 있습니다. 버그 보고서의 stderr.log에서 원인을 확인할 수 있습니다. 자동 로더로 ps5upload를 불러온다면 여기에서 전송해 보세요.",
