"fpkg.lowSpace": "여유 공간 부족: 변환에 출력 드라이브의 최대 {need}가 필요할 수 있지만 {free}만 남아 있습니다.",
"fpkg.about": "게임 폴더나 .exfat 또는 .ffpkg 마운트 이미지를 지정하세요. 변환기가 트리를 읽고, 실행 가능한 패키지에 필요한 것이 모두 있는지 확인한 뒤, 디버그 형식의 .pkg를 출력 폴더에 기록합니다.",
"fpkg.aboutWhere": "변환은 콘솔이 아니라 엔진을 실행하는 기기(이 컴퓨터, Docker 호스트 또는 Android 기기)에서 실행됩니다. 패키지를 설치하기 전까지는 콘솔에 아무것도 전달되지 않습니다. 설치는 이 컴퓨터에서 스트림하거나 먼저 PS5에 업로드하는 방식으로 합니다.",
"fpkg.aboutSource": "원본은 이미 복호화된 게임 트리여야 합니다. 정품 설치본은 여기에서 풀 수 없으며, 그런 것을 골랐다면 아래 검사가 알려 줍니다.",
"fpkg.aboutFake": "결과물은 가짜 패키지이므로, 설치 전에 콘솔에 가짜 패키지 지원을 로드해야 합니다: kstuff(PS5 가짜 패키지 지원 빌드), a53_ppr_install_fast.elf, shadowmountplus.elf를 이 순서대로. 패키지 설치 화면의 설치 버튼 옆에도 같은 내용이 있습니다.",
"fpkg.aboutChecks": "검사 항목",
"fpkg.checkEboot": "트리 루트의 eboot.bin(타이틀 모듈). 원시 ELF이거나 감싼 SELF여야 하며, 정품 서명 모듈은 다시 패키징할 수 없습니다.",
"fpkg.checkParam": "sce_sys/param.json이 있고 sce_sys/param.sfo가 없어야 합니다. param.sfo가 있으면 콘솔이 PS4 방식으로 실행합니다.",
"fpkg.checkIcons": "36자 콘텐츠 ID, 아이콘 두 개, 권한 모듈 sce_sys/about/right.sprx.",
"fpkg.checkDrm": "패키지의 DRM 값이 표준인지 확인합니다. 무료 또는 업그레이드 가능 값이면 콘솔이 타이틀을 잠급니다. 값은 패키지 안에서만 바꾸며 원본 파일은 절대 건드리지 않습니다.",
"payloads_essentials_title": "ps5upload와 함께 권장",
"payloads_essentials_body": "콘솔을 처음 설정한다면 이 세 가지로 ps5upload가 기대하는 대부분이 갖춰집니다: kstuff-lite(대부분의 홈브루가 의존하는 커널 패치), ShadowMount+(저장소의 게임 이미지 마운트), nanoDNS(콘솔을 Sony 업데이트 경로에서 떼어 놓음). 목록의 나머지는 선택 사항입니다.",
"payloads_tab_shadowmount": "ShadowMount+",
"payloads_tab_nanodns": "nanoDNS",
