"pkglib.url.title": "HTTP(S) 링크로 설치",
"pkglib.url.help": "이 컴퓨터가 여러 연결로 동시에 패키지를 내려받아 네트워크의 PS5로 넘겨 주므로, 콘솔의 느린 단일 스트림이 아니라 회선 속도로 전송됩니다. 어느 기기에도 저장하지 않으므로 100 GB 게임도 여유 공간이 필요 없습니다. 링크는 바이트 범위를 지원하는 직접 다운로드여야 합니다. 설치가 끝날 때까지 이 컴퓨터가 절전 모드로 들어가지 않게 하세요.",
