"library_mount_modal_rw_title": "읽기/쓰기 — 이 이미지를 편집할 수 있습니다",
"library_mount_modal_rw_body": "이렇게 마운트하면 파일 교체, DLC 추가, 백포트 패치 적용이 가능합니다. 마운트 편집에는 파일 브라우저를 쓰세요. 변경 사항은 이미지 파일에 바로 기록됩니다. 잘못 편집하면 게임이 부팅되지 않을 수 있고 되돌릴 수 없으니, 중요하다면 먼저 이미지를 복사하세요. PS5가 마운트된 이미지에 세이브 데이터를 스스로 기록할 수도 있습니다.",
