"notif_fs_upload_failed": "PS5로 복사 실패",
"volumes_mounted_rw": "읽기/쓰기",
"pkg.patch_loader_not_listening": "PS5의 페이로드 로더가 실행 중이지만 포트 9021에서 연결을 받지 않아 이 업데이트를 적용할 수 없었습니다. 필요한 설치 프로그램이 전달되지 않았고 콘솔은 업데이트를 받지 못했습니다. 기본 게임은 그대로입니다. 탈옥 페이지에서 로더를 다시 불러오세요. 페이로드를 이미 한 번 제공한 로더 프로세스는 계속 대기하지 않을 수 있습니다. 업데이트는 이미 PS5에 있으므로 다시 업로드할 필요는 없습니다. 패키지 목록에서 설치를 다시 시도하세요. PS5에서 직접 적용할 수도 있습니다: 설정 → 시스템 → 디버그 설정 → 게임 → Package Installer.",
"pkg.reverify_impossible": "PS5가 이 설치를 받아들였지만, ps5upload에는 설치된 패키지를 식별할 정보가 없어 확인할 수 없습니다. 결과는 PS5 알림에서 확인하세요. 준비한 패키지는 보관했습니다.",
"pkg.reverify_gave_up": "30분이 지나도 확인되지 않았습니다. 매우 큰 타이틀은 더 오래 걸릴 수 있습니다. PS5 알림을 확인하거나 다시 확인을 누르세요.",
