"joberr.ava1_commit_exists": "파일은 업로드되었지만 대상이 이미 있어 게시하지 못했습니다. 덮어쓰기를 선택해 교체하거나 다른 대상을 선택하세요.",
"joberr.ava1_cross_device": "대상이 임시 저장 영역과 다른 드라이브에 있어 PS5가 파일을 옮기지 못했습니다. 같은 드라이브의 대상을 선택하거나 먼저 내장 드라이브에 업로드하세요.",
"joberr.ava1_wrong_console": "이 주소의 장치는 이 앱과 페어링된 PS5가 아닙니다. 주소를 확인하거나 이 콘솔과 다시 페어링하세요.",
"joberr.ava1_no_identity": "이 앱에는 아직 페어링 ID가 없습니다. 연결 화면에서 PS5와 페어링한 후 다시 시도하세요.",
"joberr.zip_read_error": "이 .zip을 읽을 수 없습니다(읽는 도중 파일이나 드라이브가 사라졌을 수 있습니다). 소스가 계속 연결되어 있는지 확인하고 다시 시도를 클릭하세요.",
"joberr.ava1_zip_corrupt": "이 .zip을 읽을 수 없습니다. 손상되었거나 불완전합니다. 다시 다운로드하거나 새로 만든 후 시도하세요.",
"joberr.ava1_7z_corrupt": "이 .7z를 읽을 수 없습니다. 손상되었거나 불완전합니다. 다시 다운로드하거나 새로 만든 후 시도하세요.",
"joberr.ava1_7z_encrypted": "이 .7z는 암호화되어 있어 스트리밍할 수 없습니다. 컴퓨터에서 압축을 풀고 대신 폴더를 업로드하세요.",
"joberr.ava1_7z_unsafe_path": "이 .7z에는 안전하지 않은 파일 경로(자체 폴더를 벗어남)가 있습니다. 컴퓨터에서 압축을 풀고 대신 폴더를 업로드하세요.",
"joberr.rar_password": "이 .rar에는 암호가 필요하거나 입력한 암호가 틀렸습니다. 올바른 암호를 입력하고 다시 시도하세요.",
"joberr.rar_corrupt": "이 .rar가 손상되었거나 일부 파트가 없거나 순서가 맞지 않습니다. 모든 파트가 있는지 확인하고 다시 시도하세요.",
"joberr.ava1_copy_lost": "PS5가 이 복사를 놓쳤습니다(도우미가 다시 시작되었거나 연결이 끊김). 다시 시도를 클릭해 처음부터 시작하세요.",
"joberr.ava1_copy_failed": "PS5가 복사를 끝내지 못했습니다. 여유 공간과 원본·대상이 계속 사용 가능한지 확인한 후 다시 시도하세요.",
"joberr.ava1_local_io": "이 컴퓨터가 다운로드한 파일을 쓰지 못했습니다. 대상 폴더의 권한과 여유 공간을 확인한 후 다시 시도하세요.",
"joberr.ava1_bad_manifest": "PS5가 이 앱이 이해하지 못하는 파일 목록을 보냈습니다. 도우미와 앱을 같은 버전으로 업데이트한 후 다시 시도하세요.",
"joberr.helper_not_ava1": "PS5 도우미가 실행 중이 아닙니다. 연결 화면에서 전송하세요(배너에 표시되면 도우미 업데이트를 사용해도 됩니다). 그런 다음 다시 시도하세요.",
"joberr.helper_not_ava1_web": "PS5 도우미가 실행 중이 아닙니다. 이 웹 UI는 전송할 수 없습니다. 평소 쓰는 페이로드 로더로 콘솔에서 ps5upload 페이로드를 시작하세요(배너에 표시되면 도우미 업데이트를 사용해도 됩니다). 그런 다음 다시 시도하세요.",
"joberr.helper_old": "PS5에서 이전 도우미가 실행 중입니다. 상단 배너의 도우미 업데이트를 클릭한 후 다시 시도하세요.",
"joberr.not_paired": "이 PS5는 아직 이 앱을 수락하지 않았습니다. 페어링… 버튼으로 페어링한 후 다시 시도하세요.",
"joberr.helper_starting": "PS5 도우미가 아직 시작 중입니다. 몇 초 기다린 후 다시 시도하세요.",
"joberr.ava1_failed": "PS5 도우미는 시작되었지만 전송 서버가 시작되지 않았습니다. 콘솔을 다시 시작한 후 다시 시도하세요.",
"joberr.helper_not_running": "PS5에서 실행 중인 도우미가 없습니다. 먼저 도우미를 전송하세요(데스크톱 앱의 연결 화면 또는 페이로드 로더). 그런 다음 다시 시도하세요.",
