fs_upload_stopped_hint: "PS5에 이미 도착한 부분은 유지됩니다. 재개하면 나머지만 보냅니다.",
fs_upload_interrupted_notice: "PS5로의 복사가 중단되었습니다. 파일을 열어 재개하세요.",
installed_launch_smp_refused: "kstuff가 실행 중인데도 PS5가 이 게임의 시작을 거부했습니다 (0x80940033). ShadowMount+는 게임이 시작될 때 마운트하는데, 그 과정이 이루어지지 않았습니다. 실행 중인 게임을 닫고 Payloads에서 ShadowMount+를 다시 보낸 뒤 플레이를 누르세요.",
connection_mac_local_network_hint: "macOS가 이 앱의 로컬 네트워크 접근을 차단하고 있을 수 있습니다. 시스템 설정 → 개인정보 보호 및 보안 → 로컬 네트워크에서 PS5Upload를 허용한 뒤 다시 확인하세요.",
batch_space_tight: "{drive}: {size}이(가) 들어가지 않을 수 있습니다. PS5는 쓰는 동안 약 5분의 1을 더 확보해 두므로 약 {fits} 정도가 들어갈 것으로 보입니다. 그래도 시도할 수 있습니다.",
installed_swap_confirm_title: "먼저 {other}을(를) 닫을까요?",
installed_swap_confirm_body: "{other}이(가) 실행 중이며 PS5는 한 번에 한 게임만 실행합니다. 닫고 {name}을(를) 시작할까요? {other}의 저장하지 않은 진행 상황은 사라집니다.",
installed_swap_confirm_ok: "닫고 시작",
installed_swap_close_failed: "{other}이(가) 아직 실행 중이고 닫을 수 없어 {name}을(를) 시작하지 않았습니다. PS5에서 닫은 뒤 다시 플레이를 누르세요.",
remotePlay_np_title: "PS5 자체의 리모트 플레이 설정 켜기",
remotePlay_np_body: "PS5는 PlayStation Network에 로그인된 계정에 대해서만 리모트 플레이를 켤 수 있게 합니다. np-fake-signin {version}은 실제 PSN 로그인 없이 콘솔이 계정을 로그인된 것으로 취급하게 합니다. 실행한 뒤에는 Settings → System → Remote Play의 스위치를 켤 수 있습니다.",
remotePlay_np_step_download: "np-fake-signin-ps5.elf ({version})를 다운로드합니다.",
remotePlay_np_step_send: "Payloads에서 PS5로 보냅니다. 한 번 실행되고 종료됩니다. 계정이 이미 활성화되어 있어야 합니다.",
remotePlay_np_step_restart: "PS5를 다시 시작한 다음 Settings → System → Remote Play에서 리모트 플레이를 켭니다.",
remotePlay_np_undo: "되돌리려면: Settings → Users and Accounts → Other → Sign out.",
remotePlay_np_download: "{version} 다운로드",
remotePlay_np_open_payloads: "Payloads 열기",
library_download_resume: "다운로드 재개",
kept_title: "ps5upload가 보관 중인 항목",
kept_intro: "ps5upload가 이 콘솔에 직접 쓰는 폴더와 각 폴더의 용량입니다. 임시 파일과 테스트 파일은 정리할 수 있습니다. 패키지와 세이브 백업은 여기서 열기만 하며 삭제되지 않습니다.",
