"install.description.v2": ".pkg 및 .fpkg 패키지를 PS5에 설치합니다. 이 컴퓨터나 링크에서 바로('스트림 및 설치'), 또는 먼저 PS5에 둔 사본에서('업로드 및 설치') 설치합니다.",
faq_collapse_all: "모두 접기",
