faq_topics: "주제",
health_junk_explain_v2: "ps5upload가 만들었지만 더 이상 필요 없는 것들입니다. 전송이 중단되어 남은 미완성 파일, 임시 폴더에 한 시간 넘게 남아 있는 패키지 사본, 오래된 속도 테스트 파일이 해당합니다. ps5upload 자체 폴더만 살펴보며, 게임, 패키지, 세이브에는 절대 손대지 않습니다.",
home_health_checking: "모든 것이 정상인지 확인하는 중…",
