"speedtest.failed.upload": "PS5로 보내지 못했습니다: {error}",
"speedtest.help": "실제 복사와 같은 방식으로 테스트 파일을 PS5로 보내고 다시 읽은 다음 양쪽에서 삭제합니다. 인터넷이 아니라 이 컴퓨터와 PS5 사이의 네트워크를 측정합니다.",
"speedtest.preparing": "이 컴퓨터에 테스트 파일을 만드는 중…",
"speedtest.size": "테스트 크기",
